export const actionSchema=object({
 version:{const:2},rig:{const:'quaternius-ual1'},id,name:{type:'string',minLength:1,maxLength:64},
 phases:{type:'array',minItems:1,maxItems:32,items:object({id,name:str,intent:str,duration:{type:'number',minimum:.016,maximum:16},kind:{enum:['hold','fast','move','neutral']},clip:{enum:rigManifest.clips},from:{type:'number',minimum:0,maximum:1},to:{type:'number',minimum:0,maximum:1}},['id','name','intent','duration','clip','from','to'])},
 tracks:{type:'array',maxItems:198,items:object({target:{enum:['$root',...rigManifest.bones.map(b=>b.name)]},property:{enum:['rotation','position','scale']},mode:{enum:['absolute','offset']},interpolation:{enum:['linear','smooth','step']},keys:{type:'array',minItems:1,maxItems:512,items:keySchema}})},
 cues:{type:'array',maxItems:16,items:object({type:{const:'impact'},time:num,strength:{type:'number',minimum:.1,maximum:3}})}
},['version','rig','id','name','phases','tracks']);
const expected={type:'integer',minimum:0};
const previewSchema=object({actionId:id,time:{type:'number',minimum:0,maximum:30},playing:{type:'boolean'},speed:{type:'number',minimum:.05,maximum:2},loop:{type:'boolean'},view:{enum:['current','reference','both']},camera:{enum:['Orbit','Front','Side','Top']},grid:{type:'boolean'},effects:{type:'boolean'},idle:{type:'boolean'},metric:{enum:['pose','height']}},[]);
const movementMetadataSchema=object({source:{type:'string',minLength:1,maxLength:300},support:{enum:['both','left','right','unknown']},travel:{enum:['in-place','source']},notes:{type:'string',maxLength:500}});
function movementMetadata(v:any):MovementMetadata{if(!v||Object.keys(v).some(k=>!['source','support','travel','notes'].includes(k))||typeof v.source!=='string'||!v.source||v.source.length>300||typeof v.notes!=='string'||v.notes.length>500||!['both','left','right','unknown'].includes(v.support)||!['in-place','source'].includes(v.travel))throw Error('Invalid movement metadata');return clone(v);}
function validateRecipe(v:any){if(!v||!['pose-blend-v1','pose-blend-v2'].includes(v.compiler)||!Array.isArray(v.steps)||!v.steps.length||v.steps.length>8||!Array.isArray(v.warnings)||v.warnings.some((w:any)=>typeof w!=='string'||w.length>500)||v.steps.some((s:any,i:number)=>!s||typeof s.movementId!=='string'||!s.movementId.startsWith('move-')||!Number.isInteger(s.revision)||s.revision<1||!Number.isFinite(s.speed)||s.speed<.5||s.speed>1.5||!Number.isFinite(s.transition)||s.transition<0||s.transition>1||i===0&&s.transition!==0||i>0&&s.transition===0||s.contact!==undefined&&!['left','right'].includes(s.contact)||s.blend!==undefined&&!['pose','velocity'].includes(s.blend)||s.travel!==undefined&&!['source','continue'].includes(s.travel)||s.facing!==undefined&&!['source','continue','target'].includes(s.facing)||s.aim!==undefined&&(typeof s.aim!=='number'||s.aim<0||s.aim>1)||s.order!==undefined&&!['together','turn-first'].includes(s.order)))throw Error('Invalid action recipe');return clone(v);}
